    // Add to existing class:
    
    toLAB(): LabColor {
        const hsl = this.toHSL();
        // Convert through XYZ space for accuracy
        // Using D65 illuminant
        let r = this.red() / 255;
        let g = this.green() / 255;
        let b = this.blue() / 255;
        
        // Convert to XYZ
        r = r > 0.04045 ? Math.pow((r + 0.055) / 1.055, 2.4) : r / 12.92;
        g = g > 0.04045 ? Math.pow((g + 0.055) / 1.055, 2.4) : g / 12.92;
        b = b > 0.04045 ? Math.pow((b + 0.055) / 1.055, 2.4) : b / 12.92;
        
        const x = r * 0.4124 + g * 0.3576 + b * 0.1805;
        const y = r * 0.2126 + g * 0.7152 + b * 0.0722;
        const z = r * 0.0193 + g * 0.1192 + b * 0.9505;
        
        // Convert XYZ to Lab
        const lab = new LabColor();
        lab.l = Math.max(0, Math.min(100, 116 * this.labHelper(y) - 16));
        lab.a = Math.max(-128, Math.min(127, 500 * (this.labHelper(x) - this.labHelper(y))));
        lab.b = Math.max(-128, Math.min(127, 200 * (this.labHelper(y) - this.labHelper(z))));
        
        return lab;
    }

    static fromLAB(lab: LabColor): DynamicColor {
        const y = (lab.l + 16) / 116;
        const x = lab.a / 500 + y;
        const z = y - lab.b / 200;

        // Convert to RGB
        const rgb = new RGBColor();
        rgb.red = Math.round(Math.max(0, Math.min(255, (3.2406 * x - 1.5372 * y - 0.4986 * z) * 255)));
        rgb.green = Math.round(Math.max(0, Math.min(255, (-0.9689 * x + 1.8758 * y + 0.0415 * z) * 255)));
        rgb.blue = Math.round(Math.max(0, Math.min(255, (0.0557 * x - 0.2040 * y + 1.0570 * z) * 255)));
        
        return new DynamicColor(rgb);
    }

    private labHelper(value: number): number {
        return value > 0.008856 ? Math.pow(value, 1/3) : (7.787 * value) + 16/116;
    }
